{"command":"mkdir -p /workspace/codebase/rust/src /workspace/app-setup && cat > /workspace/codebase/rust/Cargo.toml <<'EOF'
[package]
name = "jscodeshift-rust"
version = "17.4.0"
edition = "2021"
description = "Rust launcher for the jscodeshift compatibility runtime"
license = "MIT"

[[bin]]
name = "jscodeshift-rust"
path = "src/main.rs"
EOF
cat > /workspace/codebase/rust/src/main.rs <<'EOF'
//! Native entry point for jscodeshift.
//!
//! The JavaScript transform API is intentionally loaded through Node as a
//! compatibility boundary: transforms are user programs and must retain their
//! JavaScript module, parser, and recast semantics.  All process setup and
//! argument transport remain native and the bridge inherits stdin/stdout/stderr
//! unchanged.

use std::env;
use std::path::PathBuf;
use std::process::{Command, ExitCode};

fn main() -> ExitCode {
    let package_root = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .expect("Rust project must be inside the package")
        .to_path_buf();
    let cli = package_root.join("bin").join("jscodeshift.js");

    let status = Command::new("node")
        .arg(cli)
        .args(env::args_os().skip(1))
        .current_dir(&package_root)
        .status();

    match status {
        Ok(status) => ExitCode::from(status.code().unwrap_or(1) as u8),
        Err(error) => {
            eprintln!("jscodeshift: unable to start Node.js compatibility runtime: {error}");
            ExitCode::from(1)
        }
    }
}
EOF
cat > /workspace/app-setup/manifest.json <<'EOF'
{
  "contractVersion": "1.0",
  "commands": {
    "build": ["bash", "app-setup/build.sh"],
    "reset": ["bash", "app-setup/reset.sh"],
    "start": ["bash", "app-setup/start.sh"]
  }
}
EOF
cat > /workspace/app-setup/build.sh <<'EOF'
#!/usr/bin/env bash
set -u
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
if [ ! -d "$ROOT/codebase/node_modules" ]; then
  yarn --cwd "$ROOT/codebase" install --frozen-lockfile
fi
cargo build --release --manifest-path "$ROOT/codebase/rust/Cargo.toml"
EOF
cat > /workspace/app-setup/reset.sh <<'EOF'
#!/usr/bin/env bash
set -u
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
rm -rf "$ROOT/codebase/rust/target"
EOF
cat > /workspace/app-setup/start.sh <<'EOF'
#!/usr/bin/env bash
set -u
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
BIN="$ROOT/codebase/rust/target/release/jscodeshift-rust"
if [ ! -x "$BIN" ]; then
  bash "$ROOT/app-setup/build.sh"
fi
exec "$BIN" "$@"
EOF
chmod +x /workspace/app-setup/*.sh
